import * as github from "@actions/github";
import { createActionsPlugin } from "@ubiquity-os/plugin-sdk";
import { LOG_LEVEL } from "@ubiquity-os/ubiquity-os-logger";
import { runPlugin } from "./index";
import { envSchema, pluginSettingsSchema } from "./types/index";
export default createActionsPlugin((context) => {
    const rawInputs = github.context.payload?.inputs;
    const authToken = typeof rawInputs?.authToken === "string" ? rawInputs.authToken : undefined;
    const ubiquityKernelToken = typeof rawInputs?.ubiquityKernelToken === "string" ? rawInputs.ubiquityKernelToken : undefined;
    return runPlugin({
        ...context,
        authToken,
        ubiquityKernelToken,
        adapters: {},
    });
}, {
    logLevel: process.env.LOG_LEVEL || LOG_LEVEL.INFO,
    settingsSchema: pluginSettingsSchema,
    envSchema: envSchema,
    ...(process.env.KERNEL_PUBLIC_KEY && { kernelPublicKey: process.env.KERNEL_PUBLIC_KEY }),
    postCommentOnError: true,
    bypassSignatureVerification: process.env.NODE_ENV === "local",
});
